using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.AssetImporters;
using UnityEngine;

// Project import rules for FBX generated by Tools/citygen (Blender) and for PS1 textures.
// - Models in Assets/GTA/City|DA|Props: 32-bit indices, FBX normals (flat shading), MeshCollider on every mesh
//   except road markings and LOD1+ billboards.
// - Materials (naming contract with Blender): "Foo" -> GTA/PS1Lit with T_Foo.png (white tint) if it exists,
//   else the Blender color; "Foo__Tint" -> T_Foo.png x Blender color. Textures with alpha -> cutout, double-sided.
// - Textures in Assets/GTA/Textures: point filter, no compression, no mipmaps.
class ImportRules : AssetPostprocessor
{
    const string TexDir = "Assets/GTA/Textures/";

    bool IsGenerated => assetPath.StartsWith("Assets/GTA/City/") || assetPath.StartsWith("Assets/GTA/DA/") ||
                        assetPath.StartsWith("Assets/GTA/Props/");
    bool IsCar => assetPath.StartsWith("Assets/GTA/Cars/");   // same material rules, no mesh colliders (rigidbody)

    void OnPreprocessModel()
    {
        if (!IsGenerated && !IsCar) return;
        var mi = (ModelImporter)assetImporter;
        mi.indexFormat = ModelImporterIndexFormat.UInt32;
        mi.importNormals = ModelImporterNormals.Import;
        mi.importAnimation = false;
        mi.importCameras = false;
        mi.importLights = false;
        mi.materialImportMode = ModelImporterMaterialImportMode.ImportViaMaterialDescription;
    }

    void OnPreprocessMaterialDescription(MaterialDescription description, Material material, AnimationClip[] clips)
    {
        if (!IsGenerated && !IsCar) return;
        string name = description.materialName;
        int sep = name.IndexOf("__");
        string texPath = TexDir + "T_" + (sep >= 0 ? name.Substring(0, sep) : name) + ".png";
        context.DependsOnSourceAsset(texPath);   // reimport the model when the texture appears / changes

        material.shader = Shader.Find("GTA/PS1Lit");
        description.TryGetProperty("DiffuseColor", out Vector4 diffuse);
        var color = new Color(diffuse.x, diffuse.y, diffuse.z, 1).gamma;   // FBX colors are linear
        var tex = File.Exists(texPath) ? AssetDatabase.LoadAssetAtPath<Texture2D>(texPath) : null;
        if (tex)
        {
            material.SetTexture("_BaseMap", tex);
            if (sep < 0) color = Color.white;
            var ti = AssetImporter.GetAtPath(texPath) as TextureImporter;
            if (ti && ti.DoesSourceTextureHaveAlpha())
            {
                material.SetFloat("_AlphaClip", 1);
                material.EnableKeyword("_ALPHATEST_ON");
                material.SetFloat("_Cull", 0);
                material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.AlphaTest;
            }
        }
        if (name.EndsWith("__Glass"))   // see-through glass sharing the atlas of its object
        {
            color.a = 0.45f;
            material.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.SrcAlpha);
            material.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            material.SetFloat("_ZWrite", 0);
            material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
            material.SetShaderPassEnabled("ShadowCaster", false);
        }
        material.SetColor("_BaseColor", color);
    }

    void OnPostprocessModel(GameObject root)
    {
        if (!IsGenerated) return;
        foreach (var mf in root.GetComponentsInChildren<MeshFilter>())
        {
            string n = mf.name;
            if (n.Contains("Markings") || (n.Contains("_LOD") && !n.EndsWith("_LOD0"))) continue;
            mf.gameObject.AddComponent<MeshCollider>().sharedMesh = mf.sharedMesh;
        }
        // Unity puts every *_LODn of the file into one root LODGroup: rebuild one group per parent instead.
        foreach (var g in root.GetComponentsInChildren<LODGroup>()) Object.DestroyImmediate(g);
        foreach (var parent in root.GetComponentsInChildren<Transform>())
        {
            var lod0 = parent.Cast<Transform>().FirstOrDefault(c => c.name.EndsWith("_LOD0"));
            var lod1 = parent.Cast<Transform>().FirstOrDefault(c => c.name.EndsWith("_LOD1"));
            if (!lod0 || !lod1) continue;
            parent.gameObject.AddComponent<LODGroup>().SetLODs(new[]
            {
                new LOD(0.12f, lod0.GetComponents<Renderer>()),     // billboard below ~12 % of screen height
                new LOD(0.004f, lod1.GetComponents<Renderer>()),
            });
        }
    }

    void OnPreprocessTexture()
    {
        if (!assetPath.StartsWith(TexDir)) return;
        var ti = (TextureImporter)assetImporter;
        ti.filterMode = FilterMode.Point;
        ti.textureCompression = TextureImporterCompression.Uncompressed;
        ti.mipmapEnabled = false;   // Fabien: no mipmaps, the PS1 look wants the raw pixels at every distance
        ti.wrapMode = TextureWrapMode.Repeat;
        ti.alphaIsTransparency = ti.DoesSourceTextureHaveAlpha();
    }
}
